UPDATE users u
SET role = #{params.Role},
    updated_at = NOW()
WHERE u.organization_uuid = #{params.OrgUUID}
AND u.deleted_at IS NULL
AND (
    u.external_id = #{params.UserID}
    OR 'user_' || LEFT(REPLACE(CAST(u.uuid AS text), '-', ''), 24) = #{params.UserID}

        OR u.uuid = #{params.UserUUID}

)
RETURNING

UPDATE users u
SET deleted_at = COALESCE(u.deleted_at, NOW()),
    updated_at = NOW()
WHERE u.organization_uuid = #{params.OrgUUID}
AND u.deleted_at IS NULL
AND (
    u.external_id = #{params.UserID}
    OR 'user_' || LEFT(REPLACE(CAST(u.uuid AS text), '-', ''), 24) = #{params.UserID}

        OR u.uuid = #{params.UserUUID}

)

mapper.select:
SELECT u.external_id AS user_external_id, u.organization_uuid AS org_uuid FROM users u WHERE u.deleted_at IS NULL
AND u.organization_uuid = #{preferredOrgUUID}
ORDER BY CASE WHEN u.external_id = 'user_default' THEN 0 ELSE 1 END, u.added_at ASC, u.uuid ASC LIMIT 1

SELECT u.uuid, u.external_id, u.email, NULLIF(u.name, '') AS full_name, NULLIF(u.name, '') AS display_name, true AS is_verified, true AS age_is_verified, u.added_at AS created_at FROM users u WHERE u.deleted_at IS NULL AND ( u.external_id = #{userExternalID} OR 'user_' || LEFT(REPLACE(CAST(u.uuid AS text), '-', ''), 24) = #{userExternalID}
OR u.uuid = #{userUUID}
) ORDER BY u.added_at ASC, u.uuid ASC LIMIT 1

SELECT o.uuid, o.name, CAST(NULL AS text) AS domain, CAST(NULL AS uuid) AS parent_organization_uuid, COALESCE(o.settings, CAST('{}' AS jsonb)) AS settings, o.created_at, o.updated_at, u.role, u.added_at FROM users u JOIN organizations o ON o.uuid = u.organization_uuid WHERE u.deleted_at IS NULL AND ( u.external_id = #{userExternalID} OR 'user_' || LEFT(REPLACE(CAST(u.uuid AS text), '-', ''), 24) = #{userExternalID}
OR u.uuid = #{userUUID}
) ORDER BY
CASE WHEN o.uuid = #{preferredOrgUUID} THEN 0 ELSE 1 END,
u.added_at ASC, u.uuid ASC
